  min-height: 40px;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding: 0 8px 0 14px;
  border-top: 1px solid var(--line);
}

.inspectorHistory > div {
  display: flex;
}

.notice {
  position: fixed;
  right: 292px;
  bottom: 38px;
  z-index: 60;
  display: flex;
  height: 30px;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #343434;
  border-radius: 3px;
  background: #151515;
  color: #a9a9a9;
  font-family: var(--font-geist-mono);
  font-size: 9px;
  letter-spacing: 0.04em;
  animation: notice-in 160ms ease-out;
}

.notice svg {
  width: 11px;
  color: #61b995;
}

.studioPresenting {
  grid-template:
    "header header" 48px
    "canvas canvas" minmax(0, 1fr) / minmax(0, 1fr);
}

.studioPresenting .toolRail,
.studioPresenting .inspector,
.studioPresenting .commandBar {
  display: none;
}

.studioPresenting .topbar {
  grid-template-columns: auto 1px minmax(200px, 1fr) auto minmax(200px, 1fr);
}

@keyframes notice-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 1040px) {
  .studio {
    grid-template:
      "header header" 48px
      "tools canvas" minmax(0, 1fr) / 48px minmax(0, 1fr);
  }

  .inspector {
    display: none;
  }

  .topbar {
    grid-template-columns: auto 1px minmax(140px, 1fr) auto;
  }

  .topbarCenter {
    display: none;
  }

  .notice {
    right: 12px;
  }
}

@media (max-width: 720px) {
  .studio {
    grid-template:
      "header" 44px
      "canvas" minmax(0, 1fr) / minmax(0, 1fr);
  }

  .topbar {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .headerSeparator,
  .toolRail,
  .documentTitle span,
  .headerButton,
  .headerIconButton,
  .canvasMeta,
  .miniMap {
    display: none;
  }

  .documentTitle {
    padding: 0 6px;
  }

  .topbarActions {
    padding-right: 6px;
  }

  .commandBar {
    bottom: 38px;
    grid-template-columns: 30px minmax(100px, 1fr) 30px;
    width: calc(100% - 24px);
  }

  .commandHint {
    display: none;
  }

  .canvasFooter span:nth-last-child(-n + 3) {
    display: none;
  }

  .flowControls {
    display: none !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .diagramNode,
  .notice {
    animation: none;
    transition: none;
  }
}

import type { Edge, Node } from "@xyflow/react"

export type DraftTone = "neutral" | "red" | "green" | "blue" | "violet"
export type DraftNodeKind =
  | "client"
  | "gateway"
  | "service"
  | "database"
  | "queue"
  | "note"

export type DraftNodeData = Record<string, unknown> & {
  label: string
  eyebrow: string
  detail?: string
  status?: string
  tone: DraftTone
  kind: DraftNodeKind
}

export type DraftBoundaryData = Record<string, unknown> & {
  label: string
  detail: string
}

export type DraftCanvasNode =
  | Node<DraftNodeData, "draft">
  | Node<DraftBoundaryData, "boundary">

export type DraftCanvasEdge = Edge<
  Record<string, unknown> & {
    signal?: DraftTone
  }
>

export type DraftDocument = {
  schemaVersion: 1
  meta: {
    id: string
    title: string
    updatedAt: string
  }
  graph: {
    nodes: DraftCanvasNode[]
    edges: DraftCanvasEdge[]
  }
  theme: {
    preset: "carbon"
  }
  layout: {
    direction: "TB" | "LR"
  }
}

