export function toDraftDocument(
  nodes: DraftCanvasNode[],
  edges: DraftCanvasEdge[]
): DraftDocument {
  const cleanNodes = nodes.map(
    ({ id, type, position, data, style, draggable, selectable, zIndex }) => ({
      id,
      type,
      position,
      data,
      style,
      draggable,
      selectable,
      zIndex,
    })
  ) as DraftCanvasNode[]

  const cleanEdges = edges.map(
    ({
      id,
      source,
      target,
      sourceHandle,
      targetHandle,
      type,
      label,
      data,
    }) => ({
      id,
      source,
      target,
      sourceHandle,
      targetHandle,
      type,
      label,
      data,
    })
  )

  return {
    schemaVersion: 1,
    meta: {
      id: "edge-request-path",
      title: "Edge request path",
      updatedAt: new Date().toISOString(),
    },
    graph: {
      nodes: cleanNodes,
      edges: cleanEdges,
    },
    theme: {
      preset: "carbon",
    },
    layout: {
      direction: "TB",
    },
  }
}
